const rows = $input.all().map(i => i.json).filter(r => r && r.tenant_id);
if (rows.length === 0) {
  return [{ json: { _skip: true, _reason: 'no_pending_alerts', checked_at: new Date(Date.now()).toISOString() }}];
}
const windowLabels = { '7d': 'en 7 dias', '3d': 'en 3 dias', '1d': 'maniana' };
const out = rows.map(r => {
  const days = r.days_until_expiry;
  const label = windowLabels[r.alert_window] || ('en ' + days + ' dias');
  const portalUrl = 'https://arquitai.studio/settings/billing'; // o cualquier URL frontend que dispare /billing/portal
  const subject = '[ArquitAI] Tu trial Pro expira ' + label + ' - actualiza tu metodo de pago';
  const greet = r.tenant_name ? ('Hola ' + r.tenant_name + ',') : 'Hola,';
  const html = '<p>' + greet + '</p>' +
               '<p>Tu trial de <strong>' + (r.plan_tier || 'plan') + '</strong> en ArquitAI expira <strong>' + label + '</strong> (' + new Date(r.trial_ends_at).toLocaleString('es-ES') + ').</p>' +
               '<p>Para evitar que se interrumpa tu acceso, configura tu metodo de pago en el portal de cliente:</p>' +
               '<p><a href="' + portalUrl + '" style="display:inline-block;padding:12px 24px;background:#0074d4;color:white;text-decoration:none;border-radius:6px;font-weight:600;">Gestionar suscripcion</a></p>' +
               '<p>Si has decidido no continuar, puedes ignorar este email — tu cuenta pasara a modo lectura cuando termine el trial.</p>' +
               '<p>Cualquier duda, responde a este email.</p>' +
               '<hr style="border:none;border-top:1px solid #eee;margin:24px 0;"/>' +
               '<p style="color:#888;font-size:12px;">Trial inicial: 14 dias. Tier ' + (r.plan_tier || '?') + '. Tenant: ' + (r.tenant_slug || '?') + '</p>';
  const text = greet + '\n\n' +
               'Tu trial de ' + (r.plan_tier || 'plan') + ' en ArquitAI expira ' + label + ' (' + new Date(r.trial_ends_at).toLocaleString('es-ES') + ').\n\n' +
               'Para evitar que se interrumpa tu acceso, configura tu metodo de pago en el portal de cliente:\n' + portalUrl + '\n\n' +
               'Si has decidido no continuar, puedes ignorar este email - tu cuenta pasara a modo lectura cuando termine el trial.\n\n' +
               'Cualquier duda, responde a este email.\n\n' +
               '---\nTrial inicial: 14 dias. Tier ' + (r.plan_tier || '?') + '. Tenant: ' + (r.tenant_slug || '?');
  return { json: {
    tenant_id: r.tenant_id,
    tenant_name: r.tenant_name,
    tenant_slug: r.tenant_slug,
    subscription_id: r.subscription_id,
    alert_window: r.alert_window,
    alert_window_date: new Date(r.trial_ends_at).toISOString().slice(0,10),
    email_to: r.contact_email,
    plan_tier: r.plan_tier,
    trial_ends_at: r.trial_ends_at,
    days_until_expiry: r.days_until_expiry,
    email_subject: subject,
    email_html: html,
    email_text: text
  }};
});
return out;

